package com.colavite.gestor_investimento.service;
import com.colavite.gestor_investimento.entity.*; import com.colavite.gestor_investimento.repository.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.Instant; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class CarteiraPosicaoServiceTest {
 @Mock CarteiraRepository carteiras; @Mock OperacaoRepository operacoes;
 @Test void calculaCompraVendaPrecoMedioPatrimonioELucro() { var c=new Carteira("C","C",null); var a=new Acao("PETR4","Petrobras",Mercado.BRASIL,new BigDecimal("12"),Instant.now()); when(carteiras.existsById(1L)).thenReturn(true); when(operacoes.findByCarteiraIdOrderByDataOperacaoAscIdAsc(1L)).thenReturn(List.of(new Operacao(c,a,TipoOperacao.COMPRA,new BigDecimal("10"),new BigDecimal("10"),Instant.now()),new Operacao(c,a,TipoOperacao.COMPRA,new BigDecimal("10"),new BigDecimal("14"),Instant.now()),new Operacao(c,a,TipoOperacao.VENDA,new BigDecimal("5"),new BigDecimal("12"),Instant.now()))); var p=new CarteiraPosicaoService(carteiras,operacoes).listarPosicoes(1L).get(0); assertThat(p.quantidade()).isEqualByComparingTo("15"); assertThat(p.precoMedio()).isEqualByComparingTo("12"); assertThat(p.patrimonioAtual()).isEqualByComparingTo("180"); assertThat(p.lucroPrejuizo()).isEqualByComparingTo("0"); }
 @Test void carteiraVaziaRetornaResumoSemMoedas() { when(carteiras.existsById(1L)).thenReturn(true); when(operacoes.findByCarteiraIdOrderByDataOperacaoAscIdAsc(1L)).thenReturn(List.of()); assertThat(new CarteiraPosicaoService(carteiras,operacoes).resumo(1L).porMoeda()).isEmpty(); }
}
